// Catalog ids that exist on the wire (packages/protocol/src/i18n/messages) and that nothing in the daemon produces
// yet, with the package that will (DESIGN §9.2, Appendix D.9). wire-texts.test.ts accepts exactly these as unused
// while v0.5.0 is being built; with SMURG_RELEASE_GATE=1 it accepts none. A package that starts producing an id may
// leave its row (a row for an id that IS used is ignored); P12 empties the list at integration.
//
// The ids of the three enumerated families (`permissionMode.*`, `report.outcome.*`, `attention.*`) are reached through
// their helpers (permissionModeRef, reportOutcomeRef, attentionRef) and are not listed.
import type { MessageId } from '@smurg/protocol/i18n';

type Package = 'P1' | 'P2' | 'P3' | 'P4' | 'P5' | 'P6';

