/** id → the package that will produce it. */
export const PENDING_WIRE_TEXTS: ReadonlyMap<string, Package> = new Map(
  (Object.entries(BY_PACKAGE) as [Package, readonly MessageId[]][]).flatMap(([owner, ids]) => ids.map((id) => [id, owner] as const)),
);
